CREATE OR REPLACE FUNCTION public.consume_daily_coach_credit() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE result integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF; IF public.has_pro_access(auth.uid()) THEN RETURN 0; END IF; INSERT INTO public.ai_daily_usage(user_id,local_day,used) VALUES(auth.uid(),public.coach_local_day(auth.uid()),1) ON CONFLICT(user_id,local_day) DO UPDATE SET used=ai_daily_usage.used+1 WHERE ai_daily_usage.used<3 RETURNING used INTO result; RETURN result; END $function$;
CREATE OR REPLACE FUNCTION public.reserve_study_attempt(p_user uuid, p_feature text, p_state text, p_payload jsonb) RETURNS public.study_attempts LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE result public.study_attempts; pro boolean; BEGIN IF p_user IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=p_user) THEN RAISE EXCEPTION 'Forbidden'; END IF; pro:=public.has_pro_access(p_user); IF p_feature='review' AND NOT pro THEN RAISE EXCEPTION 'Review missed questions is Pro only'; END IF; IF NOT pro THEN SELECT * INTO result FROM public.study_attempts WHERE user_id=p_user AND feature=p_feature AND free_slot; IF FOUND THEN RETURN result; END IF; IF p_feature='exam' AND jsonb_array_length(p_payload)<>15 THEN RAISE EXCEPTION 'Free sample exams contain 15 questions'; END IF; IF p_feature IN ('signs','intersections','substances','speed') AND jsonb_array_length(p_payload)<>10 THEN RAISE EXCEPTION 'Free topic quizzes contain 10 questions'; END IF; END IF; INSERT INTO public.study_attempts(user_id,feature,state,free_slot,payload) VALUES(p_user,p_feature,p_state,NOT pro,p_payload) ON CONFLICT(user_id,feature) WHERE free_slot DO NOTHING RETURNING * INTO result; IF result.id IS NULL THEN SELECT * INTO result FROM public.study_attempts WHERE user_id=p_user AND feature=p_feature AND free_slot; END IF; RETURN result; END $function$;
REVOKE ALL ON FUNCTION public.reserve_study_attempt(uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_study_attempt(uuid,text,text,jsonb) TO service_role;